/** 作文批改页本地临时缓存（与会员草稿区分：仅当前会话、离开自动存、回来恢复） */

const KEY = 'essay_correction_temp'

export interface EssayTempData {
  title: string
  prompt: string
  content_text: string
}

export function getEssayTemp(): EssayTempData | null {
  try {
    const raw = sessionStorage.getItem(KEY)
    if (!raw) return null
    const data = JSON.parse(raw) as EssayTempData
    return {
      title: typeof data.title === 'string' ? data.title : '',
      prompt: typeof data.prompt === 'string' ? data.prompt : '',
      content_text: typeof data.content_text === 'string' ? data.content_text : '',
    }
  } catch {
    return null
  }
}

export function setEssayTemp(data: EssayTempData): void {
  try {
    sessionStorage.setItem(KEY, JSON.stringify(data))
  } catch {
    // ignore
  }
}

export function removeEssayTemp(): void {
  try {
    sessionStorage.removeItem(KEY)
  } catch {
    // ignore
  }
}
