import { createRouter, createWebHistory, type RouteLocationNormalizedLoaded } from 'vue-router'
import { useAuthStore } from '@/stores/auth'

// 记录导航来源，用于判断是否从详情页返回
let navigationFrom: RouteLocationNormalizedLoaded | null = null

export function getNavigationFrom() {
  return navigationFrom
}

// 列表页滚动位置：从详情返回时恢复（Browse 为 main 容器 scrollTop，All/Search 为 window scrollY）
const scrollPositions: Record<string, number> = {}
export function setScrollPosition(routeName: string, value: number) {
  scrollPositions[routeName] = value
}
export function getScrollPosition(routeName: string): number | undefined {
  return scrollPositions[routeName]
}

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  scrollBehavior(to, from, savedPosition) {
    // 浏览器前进/后退时使用其记录的滚动位置
    if (savedPosition) return savedPosition
    // 从详情页返回到使用 window 滚动的列表页时，恢复之前保存的位置
    if (from?.name === 'ClassicItemDetail') {
      const name = to.name as string
      if (name === 'ClassicAll' || name === 'ClassicSearch') {
        const top = getScrollPosition(name)
        if (typeof top === 'number' && top >= 0) return { top, left: 0 }
      }
    }
    return { top: 0 }
  },
  routes: [
    {
      path: '/',
      name: 'Home',
      component: () => import('@/views/Home.vue'),
    },
    {
      path: '/login',
      name: 'Login',
      component: () => import('@/views/auth/Login.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/register',
      name: 'Register',
      component: () => import('@/views/auth/Register.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/forgot-password',
      name: 'ForgotPassword',
      component: () => import('@/views/auth/ForgotPassword.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/terms',
      name: 'Terms',
      component: () => import('@/views/legal/Terms.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/privacy',
      name: 'Privacy',
      component: () => import('@/views/legal/Privacy.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/about',
      name: 'About',
      component: () => import('@/views/About.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/essay/correction',
      name: 'Correction',
      component: () => import('@/views/essay/Correction.vue'),
    },
    {
      path: '/essay/history',
      name: 'History',
      component: () => import('@/views/essay/History.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/essay/:id',
      name: 'EssayDetail',
      component: () => import('@/views/essay/Correction.vue'),
      meta: { requiresAuth: true },
    },
    {
      path: '/profile',
      name: 'Profile',
      component: () => import('@/views/user/Profile.vue'),
      meta: { requiresAuth: true },
    },
    {
      path: '/membership',
      name: 'Membership',
      component: () => import('@/views/user/Membership.vue'),
      meta: { requiresAuth: true },
    },
    {
      path: '/favorites',
      name: 'Favorites',
      component: () => import('@/views/user/Favorites.vue'),
      meta: { requiresAuth: true },
    },
    {
      path: '/classic',
      name: 'Classic',
      component: () => import('@/views/classic/Index.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/classic/search',
      name: 'ClassicSearch',
      component: () => import('@/views/classic/Search.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/classic/browse',
      name: 'ClassicBrowse',
      component: () => import('@/views/classic/Browse.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/classic/all',
      name: 'ClassicAll',
      component: () => import('@/views/classic/All.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/classic/random',
      name: 'ClassicRandom',
      component: () => import('@/views/classic/Random.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/classic/item/:id',
      name: 'ClassicItemDetail',
      component: () => import('@/views/classic/ItemDetail.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/classic/essay-writing',
      name: 'ClassicEssayWriting',
      component: () => import('@/views/classic/EssayWriting.vue'),
      meta: { requiresAuth: false },
    },
    {
      path: '/admin',
      name: 'Admin',
      component: () => import('@/views/admin/Dashboard.vue'),
      meta: { requiresAuth: true, requiresAdmin: true },
      children: [
        {
          path: 'dashboard',
          name: 'AdminDashboard',
          component: () => import('@/views/admin/Dashboard.vue'),
        },
      ],
    },
    {
      path: '/:pathMatch(.*)*',
      name: 'NotFound',
      redirect: '/',
    },
  ],
})

// 路由守卫
router.beforeEach((to, from, next) => {
  const authStore = useAuthStore()

  // 记录导航来源
  navigationFrom = from

  // 检查是否需要登录
  if (to.meta.requiresAuth && !authStore.isAuthenticated) {
    next({ name: 'Login', query: { redirect: to.fullPath } })
    return
  }

  // 检查是否需要管理员权限
  if (to.meta.requiresAdmin && !authStore.isAdmin) {
    next({ name: 'Home' })
    return
  }

  // 已登录用户访问登录/注册/忘记密码页，重定向到首页
  if (
    (to.name === 'Login' || to.name === 'Register' || to.name === 'ForgotPassword') &&
    authStore.isAuthenticated
  ) {
    next({ name: 'Home' })
    return
  }

  next()
})

export default router
