// 认证工具函数

const TOKEN_KEY = 'access_token'
const REFRESH_TOKEN_KEY = 'refresh_token'
const USER_KEY = 'user_info'
const TOKEN_EXPIRES_AT_KEY = 'token_expires_at'
const REMEMBERED_ACCOUNTS_KEY = 'remembered_accounts'

const TOKEN_TTL_MS = 7 * 24 * 60 * 60 * 1000 // 7 天
const REMEMBERED_ACCOUNTS_MAX = 10
const PASSWORD_KEY_SALT = 'remembered_accounts_aes_salt_v1'

export type RememberedAccount = { emailOrPhone: string; password: string }

type StoredAccount = { emailOrPhone: string; password: string } // password 存加密串

// 派生 AES 密钥（固定盐，仅做本地混淆）
async function getPasswordKey(): Promise<CryptoKey> {
  const enc = new TextEncoder()
  const keyMaterial = await crypto.subtle.importKey(
    'raw',
    enc.encode(PASSWORD_KEY_SALT),
    { name: 'PBKDF2' },
    false,
    ['deriveKey']
  )
  return crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: enc.encode(PASSWORD_KEY_SALT),
      iterations: 100000,
      hash: 'SHA-256',
    },
    keyMaterial,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt']
  )
}

// 加密密码，返回 base64（IV + 密文）
export async function encryptPassword(plain: string): Promise<string> {
  const key = await getPasswordKey()
  const iv = crypto.getRandomValues(new Uint8Array(12))
  const enc = new TextEncoder()
  const ct = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv, tagLength: 128 },
    key,
    enc.encode(plain)
  )
  const combined = new Uint8Array(iv.length + ct.byteLength)
  combined.set(iv)
  combined.set(new Uint8Array(ct), iv.length)
  let bin = ''
  for (let i = 0; i < combined.length; i += 8192) {
    bin += String.fromCharCode(...combined.subarray(i, i + 8192))
  }
  return btoa(bin)
}

// 解密密码，输入 base64
export async function decryptPassword(cipherBase64: string): Promise<string> {
  try {
    const combined = Uint8Array.from(atob(cipherBase64), (c) => c.charCodeAt(0))
    const iv = combined.slice(0, 12)
    const ct = combined.slice(12)
    const key = await getPasswordKey()
    const dec = await crypto.subtle.decrypt({ name: 'AES-GCM', iv, tagLength: 128 }, key, ct)
    return new TextDecoder().decode(dec)
  } catch {
    return '' // 解密失败（如旧版明文）返回空
  }
}

// 存储 Token（7 天有效）
export function setToken(token: string, refreshToken?: string): void {
  localStorage.setItem(TOKEN_KEY, token)
  localStorage.setItem(TOKEN_EXPIRES_AT_KEY, String(Date.now() + TOKEN_TTL_MS))
  if (refreshToken) {
    localStorage.setItem(REFRESH_TOKEN_KEY, refreshToken)
  }
}

// 获取 Token，过期则清除并返回 null
export function getToken(): string | null {
  const expiresAt = localStorage.getItem(TOKEN_EXPIRES_AT_KEY)
  if (expiresAt && Date.now() > Number(expiresAt)) {
    clearToken()
    return null
  }
  return localStorage.getItem(TOKEN_KEY)
}

// 获取Refresh Token
export function getRefreshToken(): string | null {
  return localStorage.getItem(REFRESH_TOKEN_KEY)
}

// 清除 Token
export function clearToken(): void {
  localStorage.removeItem(TOKEN_KEY)
  localStorage.removeItem(REFRESH_TOKEN_KEY)
  localStorage.removeItem(USER_KEY)
  localStorage.removeItem(TOKEN_EXPIRES_AT_KEY)
}

// 存储用户信息
export function setUser(user: unknown): void {
  localStorage.setItem(USER_KEY, JSON.stringify(user))
}

// 获取用户信息
export function getUser(): unknown | null {
  const userStr = localStorage.getItem(USER_KEY)
  return userStr ? JSON.parse(userStr) : null
}

// 检查是否已登录
export function isAuthenticated(): boolean {
  return !!getToken()
}

// 读取原始列表（不解密）
function getStoredAccountsRaw(): StoredAccount[] {
  const raw = localStorage.getItem(REMEMBERED_ACCOUNTS_KEY)
  if (!raw) return []
  try {
    const list = JSON.parse(raw) as StoredAccount[]
    return Array.isArray(list) ? list : []
  } catch {
    return []
  }
}

// 已保存的账号列表（解密后返回）
export async function getRememberedAccounts(): Promise<RememberedAccount[]> {
  const list = getStoredAccountsRaw()
  const out: RememberedAccount[] = []
  for (const item of list) {
    const decrypted = await decryptPassword(item.password)
    const pwd = decrypted || item.password // 解密失败时按旧版明文兼容
    out.push({ emailOrPhone: item.emailOrPhone, password: pwd })
  }
  return out
}

export async function addRememberedAccount(emailOrPhone: string, password: string): Promise<void> {
  const encrypted = await encryptPassword(password)
  let list = getStoredAccountsRaw().filter((a) => a.emailOrPhone !== emailOrPhone)
  list.unshift({ emailOrPhone, password: encrypted })
  if (list.length > REMEMBERED_ACCOUNTS_MAX) list = list.slice(0, REMEMBERED_ACCOUNTS_MAX)
  localStorage.setItem(REMEMBERED_ACCOUNTS_KEY, JSON.stringify(list))
}

export function removeRememberedAccount(emailOrPhone: string): void {
  const list = getStoredAccountsRaw().filter((a) => a.emailOrPhone !== emailOrPhone)
  if (list.length) {
    localStorage.setItem(REMEMBERED_ACCOUNTS_KEY, JSON.stringify(list))
  } else {
    localStorage.removeItem(REMEMBERED_ACCOUNTS_KEY)
  }
}
