<script setup lang="ts">
import { ref, onMounted, onUnmounted } from 'vue'
import { RouterView, useRoute } from 'vue-router'
import AppHeader from './components/Layout/AppHeader.vue'
import AppFooter from './components/Layout/AppFooter.vue'
import { ArrowUp } from '@element-plus/icons-vue'
import { useAuthStore } from '@/stores/auth'

const route = useRoute()
const authStore = useAuthStore()

const showBackTop = ref(false)

function updateBackTop() {
  showBackTop.value =
    document.documentElement.scrollHeight > window.innerHeight && window.scrollY > 200
}

function scrollToTop() {
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

onMounted(() => {
  if (authStore.token) {
    authStore.fetchUser()
  }
  window.addEventListener('scroll', updateBackTop)
  window.addEventListener('resize', updateBackTop)
  updateBackTop()
})
onUnmounted(() => {
  window.removeEventListener('scroll', updateBackTop)
  window.removeEventListener('resize', updateBackTop)
})
</script>

<template>
  <div id="app">
    <div class="app-bg">
      <div class="app-bg-image" />
      <div class="app-bg-gradient" />
    </div>
    <AppHeader />
    <main class="main-content">
      <RouterView v-slot="{ Component }">
        <keep-alive
          :include="[
            'Register',
            'ClassicAll',
            'ClassicBrowse',
            'ClassicSearch',
            'ClassicItemDetail',
          ]"
          :max="30"
        >
          <component :is="Component" :key="route.path" />
        </keep-alive>
      </RouterView>
    </main>
    <AppFooter />
    <Transition name="fade-slide">
      <button
        v-show="showBackTop"
        type="button"
        class="back-top"
        title="回到顶部"
        @click="scrollToTop"
      >
        <el-icon :size="20"><ArrowUp /></el-icon>
      </button>
    </Transition>
  </div>
</template>

